/** Size and class accepted by the sidebar brand mark. */
interface OkokLogoProps {
  size?: number
  className?: string | undefined
}

/** Local workbench mark. White field is knocked out in CSS so the bars sit on the sidebar. */
const OKOK_LOGO_SRC = 'data:image/png;base64,'

/**
 * Render the OKOK mark.
 * @param props.size - width and height in px.
 * @param props.className - extra class for layout placement.
 * @returns the logo image (decorative; the wordmark carries the name).
 */
export function OkokLogo({ size = 24, className }: OkokLogoProps) {
  return (
    <img
      src={OKOK_LOGO_SRC}
      alt=""
      width={size}
      height={size}
      className={className}
      data-brand="okok"
      draggable={false}
    />
  )
}
